        assert(!reverted && address(c).balance == balBefore - balBefore && owner.balance == ownerBalBefore + balBefore);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    receive() external payable {}

    fallback() external payable {}

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        uint depositsBefore = c.depositsCount();
        uint cBalBefore = address(c).balance;
        address owner = c.owner();
        uint ownerBalBefore = owner.balance;

        c.fallback{value: amount}();

        uint cBalBeforeWithdraw = address(c).balance;
        uint depositsBeforeWithdraw = c.depositsCount();

        bool callOk = address(this).balance >= cBalBeforeWithdraw;
        require(callOk);

        c.withdrawAll();

        assert(c.depositsCount() == depositsBefore + 1 &&
               cBalBeforeWithdraw == cBalBefore + amount &&
               address(c).balance == 0 &&
               owner.balance == ownerBalBefore + cBalBeforeWithdraw);
    }
}

