        // The target must not be the zero address to avoid undefined call behavior; non-owner precondition is checked after setup.
        require(target != address(0));

        // Read before-values (setup already done by constructor / caller).
        balBefore = address(c).balance;
        depBefore = c.depositsCount();

        // Allow the test contract to own Ether if the call accidentally succeeds; but our rule is about revert.
        require(address(this).balance >= value);

        // Make the deciding call in a try/catch to observe revert without reverting the test.
        bool reverted;
        try c.sendMoney{value: value}(target, value, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The rule: since msg.sender (this contract) is not the owner, sendMoney must ALWAYS revert,
        // and c's balance and depositsCount must remain unchanged.
        assert(reverted && address(c).balance == balBefore && c.depositsCount() == depBefore);
    }

    receive() external payable {}
}

